	[100013] = {
		info = "<p>亲爱的班长~</p><p>为了进一步提高班长的游戏体验，我们于10月31日凌晨3:00对游戏进行停机维护更新。</p><p>更新内容：</p><p>1、万圣节限时活动相关资源预载。</p><p>2、更新抢位赛奖励发放详情页关于奖励发放时间的说明</p><p>活动内容请参看后续活动相关公告。</p><p><br/></p><p>万圣节活动将于10月31日15:00开启哟~欢迎班长参加本次万圣派对！</p><p>祝班长在学院生活愉快！~w~</p><p><br/></p>",
		start_time = "2019-10-31 00:00:01",
