	[100027] = {
		info = "<p>亲爱的班长~</p><p><br/></p><p>普通魂卡商店将于21:30新增可兑换学员珍妮特、索菲亚、千竹；</p><p><br/></p><p>特别提示：感恩节火鸡蛋掉落时间截止12月1日23:59。感恩节活动兑换商店将于12月4日23:59进行关闭，请有需要的班长及时兑换。</p><p><br/></p><p>祝班长在学院生活愉快～w～</p><p><br/></p>",
