		order = 2
	},
	[300009] = {
		info = "<p><span style=color: rgb(0, 176, 240);>【无面鬼神】斯卡兰斯（CV：种田梨沙）限时UP</span>！</p><p><br/></p><p>“右眼的遮罩？那是因为一只眼睛可以看得更清晰，毫厘间的误差会造成严重的损坏。”</p><p><br/></p><p>在轮换扩招内，【无面鬼神】斯卡兰斯获得概率<span style=color: rgb(0, 176, 80);>提升五倍</span>！</p><p><br/></p><p>【无面鬼神】斯卡兰斯简介：海军出身的斯卡兰斯，处事冷静，推崇正义，战斗力十分强大。平时不会将感情轻易表露，无论说什么话都面无表情，但却会在面对自妹妹的时候会展现出温柔的一面。</p><p><br/></p><p>---------活动时间---------</p><p><span style=color: rgb(0, 176, 240);>12月6日00:00~12月12日23:59</span></p><p><br/></p><p>---------补充说明---------</p><p>◇本次轮换扩招<span style=color: rgb(0, 176, 80);>消耗扭蛋券</span></p><p>◇扩招详情请点击当期扩招图片查看。</p><p><br/></p><p>最后祝您游戏愉快!</p><p>魂器学院校委会</p><p><br/></p><p><br/></p>",
		start_time = "2019-12-05 00:00:00",
