		end_time = "2019-12-25 00:00:11",
		order = 1
	},
	[100036] = {
		info = "<p>亲爱的班长~</p><p><br/></p><p>&nbsp; &nbsp; 我们计划于12月24日凌晨2:00~5:00对游戏进行停机维护更新，给班长带来的不便，敬请谅解！</p><p><br/></p><p>更新内容：</p><p><br/></p><p>1、魂器学院全新资料片【XMAS启示录：血色圣诞】相关资源；</p><p>2、学员圣诞皮肤礼包和圣诞家具礼包上架圣诞商城，并开启限时折扣！（活动结束后圣诞礼包将上架学院礼包商城并恢复原价售卖）；</p><p>3、XMAS启示录专属家具【失控警报】上架学院家具商城；</p><p>4、塞雅语音实装（CV：福圆美里）；</p><p>5、雯语音实装（CV：伊藤静）；</p><p>6、芭荼荼语音实装（CV：丰崎爱生）。</p><p><br/></p><p>祝班长在学院生活愉快！~w~</p><p><br/></p>",
		start_time = "2019-12-23 00:00:11",
		type = 2,
