		id = 340019,
		title = "350004#【花前月下】限时UP预告",
		end_time = "2020-01-03 00:00:00",
		order = 1
	},
	[340020] = {
		info = "<p><span style=color: rgb(0, 176, 240);>【花前月下】芙蕾已开启限时UP！</span></p><p><br/></p><p>-“花前月下，灼灼百朵！”（CV：茅野爱衣）</p><p><br/></p><p>在轮换扩招内，【花前月下】芙蕾获得概率<span style=color: rgb(0, 176, 240);>提升五倍</span>！</p><p><br/></p><p>【花前月下】芙蕾简介：有月下美人之称的芙蕾，是个可以一脸随和地说着残忍话的人。看上去温柔无比，实则冷酷无情，内心难以捉摸~</p><p><br/></p><p>---------活动时间---------</p><p>1月3日00:00~1月9日23:59</p><p><br/></p><p>---------补充说明---------</p><p>◇本次轮换扩招<span style=color: rgb(0, 176, 240);>消耗扭蛋券</span></p><p>◇扩招详情请点击当期扩招图片查看。</p><p><br/></p><p>最后祝您游戏愉快!</p><p>魂器学院校委会</p><p><br/></p>",
		start_time = "2020-01-03 00:00:00",
