	[320018] = {
		info = "<p>亲爱的班长~</p><p><br/></p><p><strong>【曼珠沙华行动】活动即将正式开幕！</strong></p><p><br/></p><p>活动时间：</p><p><span style=color: rgb(255, 192, 0);>1月11日维护后至1月31日23:59</span><br/></p><p><br/></p><p>活动简介：</p><p><span style=color: rgb(0, 112, 192);>一、活动剧情副本</span></p><p>活动期间，班长们可以通过协助克利斯蒂姐妹花完成活动副本、收集任务物品，兑换丰富的活动奖励！</p><p><br/></p><p><span style=color: rgb(0, 112, 192);>二、限时UP开启</span></p><p>【猩红战刃】贝蒂和【曼珠沙华】阿加莎将开启限时UP，活动期间，获得<span style=color: rgb(0, 112, 192);>概率各提升五倍</span>！</p><p>守护着彼此的贝蒂、阿加莎姐妹，在战场上不仅拥有着强烈的羁绊，彼此单独作战时也拥有强大的实力。</p><p><br/></p><p><span style=color: rgb(0, 112, 192);>三、限时活动商城</span></p><p>活动商城将在活动结束后继续开放2天，于<span style=color: rgb(255, 0, 0);>2月2日23:59关闭</span>。商城关闭后将无法兑换本次活动的所有奖励。</p><p><br/></p><p>◇具体请参看活动页面的相应介绍。</p><p><br/></p>",
		start_time = "2020-01-10 00:00:00",
