	},
	[100056] = {
		info = "<p>亲爱的班长~</p><p><br/></p><p>为了进一步提高班长的游戏体验，我们稍后将进行热更新。</p><p><br/></p><p>更新内容：</p><p>修复个别皮肤在特殊情况下功血显示不正常的问题</p><p><br/></p><p>祝班长在学院生活愉快！~w~</p><p><br/></p>",
