	[340031] = {
		info = "<p>【特别行动】限定扩招即将开启！</p><p>【学员警司】布兰琪 &amp; 【英伦匪帮】金百莉即将开启限时UP！届时，【学员警司】布兰琪 &amp; 【英伦匪帮】金百莉获得概率各提升五倍！</p><p><br/></p><p>---------活动时间---------</p><p>2月1日00:00~2月7日23:59&nbsp;</p><p><br/></p><p>---------补充说明---------</p><p>◇本次轮换扩招消耗扭蛋券。</p><p>◇扩招详情请点击当期扩招图片查看。</p><p><br/></p><p>最后祝您游戏愉快！</p><p><br/></p><p>魂器学院校委会</p><p><br/></p>",
