	[100062] = {
		info = "<p>亲爱的班长~</p><p><br/></p><p>情人节悄然临近~</p><p>校委会特别准备了一些活动，预祝班长和心爱的学员度过一个快乐的情人节！现在先来提前了解一下吧~</p><p><br/></p><p>一、《魂器学院x料理次元》限时联动活动第二弹【巧心饰爱】即将甜蜜开启！</p><p>活动内容：2月14日0:00，限时开启【甜降正义】巧克力扩招，巧克力获得概率限时提升5倍。</p><p>同时，活动商城将限时上架巧克力养成礼包。</p><p><br/></p><p>二、情人节福利活动</p><p>1、2月14日0:00~2月25日23:59，情人节活动商店限时开放，班长可使用好感币兑换情人节礼物、巧克力专属魂智能武器、弹幕礼物等丰富道具。</p><p>2、2月14日0:00~2月16日23:59，挂机和快速搜寻均可掉落好感币！</p><p>3、2月14日情人节当日，在宿舍给学员赠送礼物，可以获得双倍好感度！</p><p><br/></p><p>三、2月14日，爱丽丝生日快乐！</p><p>爱丽丝生日当天，邮箱内限时寄送爱丽丝生日限定明信片，活动商城还将上架爱丽丝生日礼包和养成礼包，欢迎班长陪伴爱丽丝度过一个难忘的生日！</p><p><br/></p><p>四、情人节特供时装&amp;礼包</p><p>2月14日0:00~2月25日23:59，情人节时装【蜜意圣代】（爱丽丝）、【初拥之爱】（安娜）、【惊喜快递】（艾丝翠德）将上架活动商城，并开启限时折扣。</p><p>活动商城还将限时上架超值礼包【表白扭蛋礼包】，欢迎班长购买！</p><p><br/></p><p>五、学员应援活动</p><p>2月14日0:00~2月16日23:59，班长可前往梦境学区为心爱的学员赠送弹幕礼物进行应援。</p><p>同时，班长可在应援榜上查看自己的应援贡献，也可在人气榜上查看喜爱学员的即时人气排行。</p><p>应援活动共持续3天，活动结束后，校委会将慎重参考应援活动中学员的人气排行榜相应地绘制誓约皮肤哦~誓约系统敬请期待！</p><p><br/></p><p>预祝班长情人节愉快~w~</p><p><br/></p>",
		start_time = "2020-02-13 12:00:03",
