	[340043] = {
		info = "<p>02月23日是学员伊文捷琳的生日，一起为她庆生吧！</p><p>活动生日商城将全新上架伊文捷琳的生日服装【娇心伊许】，并将在伊文捷琳生日当天开启售卖及限时折扣（生日结束将上架学院服装礼包商城并恢复原价进行售卖），欢迎班长前往欣赏~</p><p>此外，【伊文捷琳生日礼包】和【伊文捷琳生日补给包】将在伊文捷琳生日当天限时供应，欢迎班长前往购买！</p><p>【伊文捷琳生日礼包】（限购1次）详情：</p><p>【伊文捷琳家具套】*1：每小时增加3枚好感币，如果该宿舍纳入【伊文捷琳】学员，则每小时增加4枚好感币；</p><p>【生日礼物】*5：每个生日礼物增加120点好感度；</p><p>【生日专属头像】*1；</p><p><br/></p><p>【伊文捷琳生日补给礼包】详情请参看活动生日商城内礼包相应介绍，欢迎班长前往购买！</p>",
		start_time = "2020-02-23 00:00:00",
