	[100066] = {
		info = "<p>亲爱的班长~</p><p><br/></p><p>学院全新资料片《穹顶沙渊》正式启幕，欢迎班长带领学员们踏上新的征程！</p><p><br/></p><p>◇ 阶段一活动</p><p>1. 主线第八章【拉弥亚·上】开放；</p><p>掉落说明：</p><p>简单难度掉落货币[天泽香]；</p><p>困难难度掉落货币[查戎信物]；</p><p>地狱难度掉落货币[巴克文森金属]；</p><p> PS：&nbsp;通关简单8-10将会获得【巴兰之诫】摩洛娜！</p><p><br/></p><p>2.「真理守护者」限时扩招开放；</p><p>开放时间：2月28日更新后~3月29日23:59</p><p>活动说明：新学员【赤影】黑木幸、【巴兰之诫】摩洛娜、【凰羽】芸加入学院，其中MR学员【赤影】黑木幸获取概率限时提升5倍！UR学员【巴兰之诫】摩洛娜、【凰羽】芸获取概率限时提升3倍！</p><p><br/></p><p>3.「限时委托」开放；</p><p>开放时间：2月28日更新后~3月29日23:59</p><p>活动说明：完成限时任务获得丰厚奖励。</p><p><br/></p><p>4.活动商城「黑街交易」开放；</p><p>开放时间：2月28日更新后-3月31日 23:59:59</p><p>活动说明：班长可使用拉弥亚主线掉落的货币在黑街兑换丰富物资。</p><p><br/></p><p>5.「特勤支援」商城开放；</p><p>开放时间：2月28日更新后-3月31日23:59</p><p><br/></p><p>◇ 阶段二活动</p><p>开放时间：3月6日更新后</p><p>1.主线第九章【拉弥亚·下】开放，货币掉落同主线第八章；</p><p>2. 危机试炼开放；</p><p>活动说明：首通获取丰厚物资！</p><p><br/></p><p>※其他说明：</p><p>1.活动结束后，「特勤支援」、「黑街交易」将关闭，活动货币结束掉落并移除。</p><p>2.请班长们规划好时间，及时完成活动任务、搬运活动物资。</p>",
		start_time = "2020-02-28 00:00:10",
		type = 2,
		id = 100066,
