	[340054] = {
		info = "<p><span style=color: rgb(0, 112, 192);>【特别行动】扩招即将开启！</span></p><p><br/></p><p>【杀戮魔镰】萱即将开启限时UP！</p><p>届时，【杀戮魔镰】萱获得<span style=color: rgb(0, 112, 192);>概率提升5倍</span>！</p><p><br/></p><p>---------活动时间---------</p><p><span style=color: rgb(0, 112, 192);>3月14日0:00-3月20日23:59</span></p><p><br/></p><p>---------补充说明---------</p><p>◇本次轮换扩招<span style=color: rgb(0, 112, 192);>消耗扭蛋券</span>。</p><p>◇扩招详情请点击当期扩招图片查看。</p><p><br/></p><p>最后祝您游戏愉快！</p><p>魂器学院校委会</p><p><br/></p>",
