	[340055] = {
		info = "<p>亲爱的班长~</p><p><br/></p><p>&nbsp; 3月19日是风纪委员希尔瑞斯的生日，届时，班长可通过点击主城活动入口，开启与希尔瑞斯的剧情对话。</p><p><br/></p><p>&nbsp; 看上去颇为严肃的希尔瑞斯，其实也有着少为人知的一面哦~班长不妨走进她的内心，去了解她的真正想法吧~</p>",
