		id = 340061,
		title = "340018#珍妮特生日快乐",
		end_time = "2020-04-05 23:59:59",
		order = 1
	},
	[340061] = {
		info = "<p><span style=color: rgb(255, 192, 0);>【空导机兵】珍妮特限时UP开启！</span></p><p><br/></p><p>-“我会为大家进行完美的空中援护~”（CV：大空直美）</p><p><br/></p><p>---------活动时间---------</p><p><span style=color: rgb(255, 192, 0);>4月3日00:00~4月9日23:59</span></p><p>活动期间，【空导机兵】珍妮特获得<span style=color: rgb(255, 192, 0);>概率提升5倍</span>！</p><p><br/></p><p>【空导机兵】珍妮特简介：珍妮特拥有高超的飞行技巧与飞行加速能力，来到学院后改用拥有高效辅助修正的光子集束枪当武器。</p><p><br/></p><p>---------补充说明---------</p><p>◇本次轮换扩招<span style=color: rgb(255, 192, 0);>消耗扭蛋券</span>。</p><p>◇扩招详情请点击当期扩招图片查看。</p><p><br/></p><p>最后祝您游戏愉快!</p><p>魂器学院校委会</p><p><br/></p>",
