	[100091] = {
		info = "<p>亲爱的班长~</p><p><br/></p><p>【超频战场】玩法再度升级！</p><p>“世界属于AI”<br/></p><p><br/></p><p>超频战场内，X-0来袭！班长可以前往挑战更加强大的AI BOSS。</p><p>上阵五支队伍即可进行挑战，每五次挑战为一次结算周期，BOSS失去的血量将对应转化为分数，分数可用于兑换[扭蛋券]、[限定勋章]、[限定头像]等稀有物资。<br/></p><p>※玩法详情请参看游戏内【超频战场】说明。</p><p><br/></p><p>祝班长游戏愉快！</p>",
