		end_time = "2020-05-21 23:59:59",
		order = 0
	},
	[340085] = {
		info = "<p><span style=color: rgb(0, 176, 80);>【次元魔方】爱丽丝·鲁比克</span>限时登场！\n</p><p><span style=color: rgb(0, 176, 240);>来和我比试下手速吧！</span></p><p>在扩招内，【次元魔方】爱丽丝<span style=color: rgb(0, 176, 240);>获得概率提升</span>！</p><p>\n</p><p>【次元魔方】爱丽丝简介：身为千金大小姐的爱丽丝对待他人总是彬彬有礼，一副天真无邪的样子非常惹人喜爱。</p><p>\n</p><p><span style=color: rgb(0, 176, 240);>---------活动时间---------</span></p><p><span style=color: rgb(0, 176, 80);>5月22日00:00~5月29日00:00</span></p><p>\n</p><p><span style=color: rgb(0, 176, 240);>---------补充说明---------</span></p><p>◇本次扩招<span style=color: rgb(0, 176, 80);>消耗扭蛋券</span></p><p>◇扩招详情请点击当期扩招图片查看。</p><p>最后祝您游戏愉快\n魂器学院校委会</p>",
