	[340086] = {
		info = "<p>亲爱的班长~</p><p>不和平的世界里，心的距离不曾有沟堑，学员们最真挚的情感，安放在了一个人的身上――班长，这样的热切，你一定感受到了吧？！</p><p><br/></p><p>【爱的表白季】活动介绍</p><p>一、如期而至</p><p>活动时间：5月20日-6月12日</p><p>活动介绍：七日签到开启！参与每日签到，获取丰富好礼！</p><p>二、告白信物</p><p>活动时间：5月20日-6月12日</p><p>活动介绍：告白信物商店限时开启，上架了表白之证礼包、真爱之礼礼包、勇气之约礼包三款超值折扣礼包。</p><p>三、纯白之约</p><p>活动时间：5月20日-6月12日</p><p>活动介绍：完成任务获取积分，收获丰富奖励！还可开启特殊约定，解锁进阶奖励，轻松获得【誓约之戒】、以及扭蛋券等好礼，开启典藏版本还可额外获得凯茜睡衣皮肤【温情夜话】及1000点积分哦！</p><p>四、勇气之礼</p><p>活动时间：5月20日-5月24日</p><p>活动介绍：活动期间，宿舍送礼次数不限（免费送礼次数增至6次）。获取更多好感度可以进一步获得学员的信赖哦~</p><p>五、真爱应援</p><p>活动时间：5月20日-5月24日</p><p>活动介绍：第三届学员应援大赛开启！在梦境学区使用应援道具，即可为心爱的学员应援打CALL，本期应援人气最高的学员将是第三批优先推出誓约皮肤的学员~</p><p>Ps：梦境学区第4章已经开启，欢迎班长前往探索</p><p>六、分享得好礼</p><p>活动时间：5月20日-6月12日</p><p>活动介绍：累积分享任意七日，即可获得扭蛋券、礼物兑换券等丰厚奖励！ </p><p><br/></p><p>特别说明：</p><p>◇本批推出的誓约皮肤学员为：风魔胧，柳生熏，妮妮珐，索菲亚以及卡米拉。</p><p>◇学员誓约皮肤将分批次上线，本批推出的学员誓约皮肤将在完成誓约后获得噢！</p>",
		start_time = "2020-05-20 00:00:01",
		type = 4,
		id = 340086,
		title = "360015#爱的表白季，开启！",
		end_time = "2020-06-12 23:59:59",
		order = 0
	},
