	[100097] = {
		info = "<p>亲爱的班长~</p><p>为了提高班长大人的游戏体验，我们将在稍后对游戏进行热更新班长可在重新进入游戏时获取更新~</p><p><br/></p><p>更新内容如下：</p>一、新学员-【灼血狐焰】那须野 红叶<p>热能系MR学员【灼血狐焰】那须野 红叶入学！</p><p>活动时间：5月30日00：00至6月12日23:59，那须野 红叶获取概率限时提升！</p><p>活动期间还会上架多款红叶专属礼包。</p><p><br/></p><p>二、新增改动：</p><p>1、原一日三签功能改为月签到，将于6月1日生效。</p><p>2、实装了诺诺妮娅婚纱皮肤【爱若心焚】的Live2D效果。</p><p>3、实装了以下角色的cv配音：凯茜、康茨坦丝、玛姬、奈奈、伊莉莎</p><p>4、新开放了八个宿舍</p><p>5、【苍蓝咆哮】希艾姆将于此次更新后加入标准扩招。</p><p>6、新增了月卡到期提醒功能。</p><p><br/></p><p>三、bug修改：</p><p>1、修复魂武核心跳转至喵酱小铺出错的问题</p><p>2、修正斯卡兰斯偶尔不能触发击退的问题</p><p>3、修复梦境学区所投放的勋章品质错误的问题</p><p>4、优化了学员突破图灵新钞不足时的跳转体验</p><p>5、优化了宿舍皮肤排序体验</p><p>6、修复了boss手术机器人buff与描述不符的问题</p><p>7、优化了柳生薰誓约皮肤【交杯之谊】的大招背景</p><p>8、修正了编队系统错乱的问题</p> <p><br/></p><p>祝班长游戏愉快！</p>",
		start_time = "2020-05-29 00:00:00",
