		end_time = "2020-05-31 23:59:59",
		order = 0
	},
	[4101008] = {
		info = "<p>06月01日是伊卡洛维的生日，伊卡洛维同学，生日快乐！</p><p><br/></p><p>活动当天，生日商城全新上架伊卡洛维生日换装【纯真时光】，并开启限时售卖，欢迎班长前往欣赏~</p><p><span style=color: rgb(255, 192, 0);>※【纯真时光】为限时皮肤只售卖1天！</span></p><p><br/></p><p>此外，【伊卡洛维生日礼包】和【伊卡洛维生日补给礼包】也将在伊卡洛维生日当天限时供应，欢迎班长前往购买！</p><p><br/></p><p>【伊卡洛维生日礼包】（限购1次）详情：</p><p>【伊卡洛维家具套】*1：每小时增加3枚好感币，如果该宿舍纳入【伊卡洛维】学员，则每小时增加4枚好感币；</p><p>【生日礼物】*5：每个生日礼物增加120点好感度且不占用送礼次数；</p><p>【生日专属头像】*1；</p><p><br/></p><p>【伊卡洛维生日补给礼包】详情请参看活动生日商城内礼包相应介绍，欢迎班长前往购买！</p><p><br/></p>",
