	[4101009] = {
		info = "<p>亲爱的班长~</p><p><br/></p><p>&nbsp;6月6日是霓昂的生日，届时，班长可通过点击主城活动入口，观看与霓昂的剧情对话。</p><p><br/></p><p>&nbsp;喜爱旧时代科学的霓昂，会在生日时展现怎样的自己呢？</p>",
