	[100100] = {
		info = "<p><span style=color: rgb(255, 192, 0);>【赤影】黑木幸限时UP</span></p><p>活动期间内，获得<span style=color: rgb(255, 192, 0);>概率提升</span>！</p><p><br/></p><p>【赤影】黑木幸简介：黑木幸出生在洛加尔传统家庭之中，父母自小就将她送到新式的机构内学习作战技巧。她表现出对武技的才能和学习天赋，让她在同伴之中脱颖而出。</p><p><br/></p><p>“可以的话请不要找我闲聊！”</p><p><br/></p><p>---------活动时间---------</p><p><span style=color: rgb(255, 192, 0);>6月6日00:00~6月19日23:59</span></p><p>---------补充说明---------</p><p><br/></p><p>◇本次扩招<span style=color: rgb(255, 192, 0);>消耗扭蛋券</span>。</p><p>◇扩招详情请点击当期扩招图片查看。</p><p><br/></p><p>最后祝您游戏愉快!</p><p>魂器学院校委会</p><p><br/></p>",
		start_time = "2020-06-06 00:00:00",
