	[100150] = {
		info = "<p>亲爱的班长～</p><p><br/></p><p>【中元节】系列活动正式开幕！</p><p><br/></p><p>活动时间：</p><p>9月2日~9月15日23:59</p><p><br/></p><p>活动简介：</p><p>1、【中元节】集字活动</p><p>◇活动时间：9月2日~9月15日23:59</p><p>◇活动期间内，请收集<span style=color: rgb(227, 98, 56);>【魂火】</span>兑换丰厚奖励吧。</p><p>◇活动期间内，<span style=color: rgb(227, 98, 56);>【魂火】</span>将通过关卡挂机、礼包购买、签到获得。</p><p>◇活动结束后，<span style=color: rgb(227, 98, 56);>【魂火】</span>将会自动转化为好感币（每个<span style=color: rgb(227, 98, 56);>【魂火】</span>转化为1好感币），请及时使用。</p><p>◇部分奖励有兑换次数上限，到达上限后将不能再次兑换。</p><p><br/></p><p>2、【祥开中元】七日签到</p><p>活动时间：9月2日~9月15日23:59</p><p>◇活动期间内可以领取<span style=color: rgb(227, 98, 56);>【魂火】</span>、【魂晶】、【礼物兑换券】等多项奖励。</p><p><br/></p><p>3、中元节限时礼包 </p><p>◇活动时间：9月02日~9月15日23:59</p><p>◇班长可以在活动期间内前往节日商店购买希有道具。</p><p><br/></p><p>最后祝您游戏愉快!</p><p><br/></p><p>魂器学院校委会</p>",
		start_time = "2020-09-02 00:00:01",
