	[100182] = {
		info = "<p>【魂器学院】<span style=color: rgb(255, 255, 0);>万圣节狂欢派对</span>来袭~！</p><p><br/></p><p>活动时间：</p><p><br/></p><p><span style=color: rgb(255, 255, 0);>10月29日更新后 一 11月10日23:59</span></p><p><br/></p><p><span style=color: rgb(255, 255, 0);>1.【限时扩招】开放</span></p><p><br/></p><p>【森罗万象】依芙限定返场，洛卡娜、妮妙、安娜、莱拉等稀有角色加入【万圣特别扩招】</p><p><br/></p><p><span style=color: rgb(255, 255, 0);>2.【万圣狂欢】开放</span></p><p><br/></p><p>完成支援任务，可获得洛卡娜动态头像及大量物资补给。解锁典藏可获得洛卡娜万圣皮肤</p><p><br/></p><p><span style=color: rgb(255, 255, 0);>3.【南瓜灯会】开放</span></p><p><br/></p><p>消耗蜡烛参与南瓜灯会，可获得万圣节限定家具套装，全新SP魂器，整套红色芯片，万圣限定皮肤等</p><p><br/></p><p><span style=color: rgb(255, 255, 0);>4.【蜡烛补给】开放</span></p><p><br/></p><p>消耗钻石或礼品卡购买万圣蜡烛，参与【南瓜灯会】赢取万圣节限定奖励</p><p><br/></p><p><span style=color: rgb(255, 255, 0);>5.【万圣探险】开放</span></p><p><br/></p><p>万圣专属探险本限时开启，体验即可获得万圣蜡烛、万圣节礼物等奖励</p><p><br/></p><p><span style=color: rgb(255, 255, 0);>6.【万圣商店】开放</span></p><p><br/></p><p>万圣节皮肤、礼包限时折扣出售</p><p><br/></p><p><span style=color: rgb(255, 255, 0);>7.【万圣签到】开放</span></p><p><br/></p><p>活动期间，累计签到达到指定天数，可领取万圣蜡烛和“万圣节”限定勋章</p><p><br/></p><p><span style=color: rgb(255, 255, 0);>8.【万圣分享】开放</span></p><p><br/></p><p>活动期间，累计分享达到指定天数，可获取依芙扭蛋券</p><p><br/></p><p></p>",
		start_time = "2020-10-29 00:00:01",
		type = 4,
