	[100193] = {
		info = "<p>《魂器学院》×《干物妹！小埋 R》联动正式上线，新学员、新皮肤、新活动玩法来袭，海量福利不容错过 ~</p><p><br/></p><p>活动时间：</p><p><br/></p><p>11月20日0:00 一 12月17日23:59</p><p><br/></p><p>1.【联动限定扩招】</p><p><br/></p><p>新增联动限定扩招，活动期间内，班长可以通过消耗干物妹扭蛋券抽取联动限定学员土间埋、橘·希尔芬福特、本场切绘、海老名菜菜。</p><p><br/></p><p>干物妹扭蛋券可通过直购获得。</p><p><br/></p><p>2.【联动皮肤礼包】</p><p><br/></p><p>新增联动皮肤超值礼包，礼包内包含土间埋「樱色和春」、海老名菜菜「朝服熏风」、本场切绘「正月晴岚」、橘·希尔芬福特「明凪流花」四款和服皮肤。</p><p><br/></p><p>3.【联动关卡】</p><p><br/></p><p>新增《干物妹！小埋 R》联动剧情关卡，班长可以在活动期间内前往参与，领取干物妹扭蛋券、礼物等丰厚奖励。</p><p><br/></p><p>4.【干物妹支援】</p><p><br/></p><p>新增联动限时支援活动，活动期间内完成联动限时支援任务，即可领取新学员金刚光以及其它物资补给。</p><p><br/></p><p>解锁典藏还可直接获得金刚光联动限定皮肤「天体观察」。</p><p><br/></p><p>5.【UMR杯！电子大赛！】</p><p><br/></p><p>新增联动挑战活动，班长可以在活动期间内前往挑战。</p><p><br/></p><p>6.【联动家具直购礼包】</p><p><br/></p><p>新增联动家具直购礼包，活动期间内，班长可以前往选购联动限定家具。</p><p><br/></p><p>7.【联动超值扭蛋礼包】</p><p><br/></p><p>新增联动专属扭蛋超值礼包，并附送埋联动专属魂器、礼物、材料等奖励。</p><p><br/></p><p>8.【干物妹回礼】</p><p><br/></p><p>新增联动限时累计充值、限时扩招活动，活动期间内完成联动限时任务，即可领取小埋联动系列角色魂武等丰厚奖励。</p><p><br/></p><p>更可解锁超稀有限定皮肤「U·M·R」以及「UMR动态头像」。</p><p><br/></p><p>9.【干物妹签到】</p><p><br/></p><p>新增联动签到活动，活动期间内累计签到达到指定天数，即可领取小埋联动系列扭蛋券等丰厚奖励。</p><p><br/></p><p>10.【干物妹分享】</p><p><br/></p><p>新增联动分享活动，活动期间内，除了每日分享奖励外，班长还可累计分享达到指定天数，即可领取干物妹扭蛋卷。</p>",
		start_time = "2020-11-20 00:00:01",
		type = 3,
		id = 100193,
		title = "1441001#干物妹!小埋 R联动开启",
		end_time = "2020-12-17 23:59:59",
		order = 0
	},
	[100194] = {
		info = "<p><span style=color: rgb(255, 192, 0);>【干物妹！小埋R】联动绝版学员限时登场！</span></p><p>【UMR军团】四位学员：土间埋、橘·希尔分福特、海老名菜菜、本场切绘，降临扩招！</p><p>在限时扩招内，四位联动学员获得<span style=color: rgb(255, 192, 0);>概率提升至2%</span>！</p><p><br/></p><p>【干物妹】土间埋简介：早点回家享受可乐吧！</p><p>【天真花束】橘·希尔分福特简介：初次见面，我是橘·希尔芬福特。</p><p>【美味天国】海老名菜菜简介：没，没什么……只是视线有点……</p><p>【梦想绘笔】本场切绘简介：抱歉……我还没有自报姓名，我的名字是本场切绘……</p><p><br/></p><p>---------活动时间---------</p><p><span style=color: rgb(255, 192, 0);>11月20日~12月17日23:59</span></p><p>---------补充说明---------</p><p><br/></p><p>◇本次扩招<span style=color: rgb(255, 192, 0);>仅能使用干物妹联动专属扭蛋券</span>。</p><p>◇扩招详情请点击当期扩招图片查看。</p><p><br/></p><p>◇【UMR军团】第五位学员可参与联动活动获得！</p><p>【星辰光辉】金刚光简介：光很擅长这个的说。</p><p><br/></p><p>最后祝您游戏愉快!</p><p>魂器学院校委会</p><p><br/></p>",
		start_time = "2020-11-20 00:00:01",
