	},
	[100205] = {
		info = "<p>【关注官方微信公众号领取福利】</p><p><br/></p><p>1.微信搜索公众号【魂器学院手游】</p><p>2.关注后点击底部菜单栏【最新活动】即可领取礼包码</p><p>3.礼包码可在游戏内【设置】进行兑换</p>",
